function annexLink(track,page,location){
 const file=track==='deck'?'Annex-II-Competency-Mapping-Officer-in-Charge-of-a-Navigational-Watch.pdf':'ANNEX-IV-Competency-Mapping-Officers-In-Charge-of-an-Engineering-Watch_11192020.pdf';
 const annex=track==='deck'?'II':'IV';
 return `<a target="_blank" rel="noopener" href="https://stcw.marina.gov.ph/wp-content/uploads/2016/02/${file}#page=${page}">MARINA Annex ${annex} · ${esc(location)} · p. ${page}</a>`;
}
