const citedMappings=[
 [['nw-1','nw-2'],'1.2',2,'The question tests position by course, distance and estimated drift.'],
 [['nw-8','nw-10','nw-11','nw-12'],'1.5',4,'The question concerns echo-sounder equipment or interpretation of its return.'],
 [['nw-15','nw-16','nw-17','nw-18'],'1.6',5,'The question tests compass compensation or correction of a compass heading.'],
 [['ew-354','ew-524','ew-525','ew-607','ew-862'],'4.1',6,'The question tests how a diesel engine exchanges air and exhaust gases.'],
 [['ew-553','ew-886','ew-887'],'4.1',6,'The question asks about the construction or purpose of a pump component.'],
 [['ew-97','ew-481','ew-708'],'4.3',7,'The question asks the learner to identify a machinery fault from a change in turbocharger speed.'],
 [['ew-150','ew-151','ew-1017'],'5.1',8,'The question connects pump operation with flow, head or required power.'],
 [['ew-922','ew-930','ew-932','ew-971','ew-979','ew-981','ew-1028'],'5.1',8,'The question asks how suction conditions affect pump behaviour.']
];
const citedById=new Map(citedMappings.flatMap(([ids,kup,page,reason])=>ids.map(id=>[id,{kup,page,reason}])));
function questionCitation(q){
 const ref=citedById.get(q.id);
 if(!ref)return '';
 return `<p class="tl-notice">${annexLink(q.track,ref.page,'F1 C'+ref.kup)}<br>${esc(ref.reason)}</p>`;
}
function mappedCompetencies(q){
 const citation=citedById.get(q.id);
 if(citation)return [Number(citation.kup.split('.')[0])];
 const entries=operationalTracks[q.track]?.flatMap(group=>group[1])||[];
 return entries.flatMap((entry,i)=>entry[1].test(q.question)?[i+1]:[]);
}
function trackFilter(q){
 if(state.screen!=='bank'||!state.functionCode)return true;
 if(state.functionCode==='pending')return !q.codes?.length;
 const groups=operationalTracks[state.track];
 const f=Number(state.functionCode)-1;
 if(!groups[f])return true;
 const start=groups.slice(0,f).reduce((n,g)=>n+g[1].length,1);
 return (q.codes||[]).some(c=>state.competencyCode?c===Number(state.competencyCode):c>=start&&c<start+groups[f][1].length);
}
function trackControls(){
 const groups=operationalTracks[state.track];
 const option=(value,label,selected)=>`<option value="${value}" ${String(value)===selected?'selected':''}>${esc(label)}</option>`;
 const f=Number(state.functionCode)-1, group=groups[f];
 const start=groups.slice(0,Math.max(0,f)).reduce((n,g)=>n+g[1].length,1);
 const code=Number(state.competencyCode);
 const page=group?annexPages[state.track][(code||start)-1]:1;
 const location=group?'F'+(f+1)+(code?' C'+code:''):'Function overview';
 return `<div class="tl-tools"><label>Function<select id="tl-function"><option value="">All functions</option>${groups.map((g,i)=>option(i+1,'F'+(i+1)+' · '+g[0],state.functionCode)).join('')}${option('pending','Awaiting mapping',state.functionCode)}</select></label>${group?`<label>Competency<select id="tl-competency"><option value="">All competencies in F${f+1}</option>${group[1].map((c,i)=>option(i+start,'C'+(i+start)+' · '+c[0],state.competencyCode)).join('')}</select></label>`:''}</div><small>${annexLink(state.track,page,location)} · Question assignments are Toolbox interpretations.</small>`;
}

